-- 0010 — the three reporting views. docs/tasks/110-reporting-views-and-screens.md.
--
-- Generated by `drizzle-kit generate` from packages/db/schema/views.ts's
-- `pgView(name, columns).as(sql\`...\`)` calls — NOT hand-appended like migrations
-- 0003-0009's triggers. views.ts passes the exact SQL text below directly (a
-- ManualViewBuilder, not the query-builder `.as((qb) => ...)` form) precisely so nothing
-- is generated FROM a query-builder chain for logic this correctness-critical — what you
-- read here is byte-for-byte what views.ts wrote, confirmed by re-running
-- `db:generate` and diffing. See views.ts's own top comment for the full reasoning
-- behind each view's shape (signed net_balance vs net_amount, the category derivation,
-- why source_type is exposed rather than filtered here).
--
-- No maintained summary table exists anywhere in this migration (bible §4.2 rule 7).
-- Every one of these three views is recomputed from journal_lines on every query.
--
-- 0000-0009 are already applied and are therefore never edited (bible §2 rule 8).
CREATE VIEW "public"."v_account_balance" AS (
  select
    je.org_id as org_id,
    jl.store_id as store_id,
    jl.account_id as account_id,
    je.period_id as period_id,
    a.code as account_code,
    a.name as account_name,
    a.type as account_type,
    a.normal_balance as normal_balance,
    coalesce(sum(jl.debit), 0)::numeric(14,2) as debit_total,
    coalesce(sum(jl.credit), 0)::numeric(14,2) as credit_total,
    (case
      when a.normal_balance = 'debit' then coalesce(sum(jl.debit), 0) - coalesce(sum(jl.credit), 0)
      else coalesce(sum(jl.credit), 0) - coalesce(sum(jl.debit), 0)
    end)::numeric(14,2) as net_balance
  from journal_lines jl
  join journal_entries je on je.id = jl.entry_id
  join accounts a on a.id = jl.account_id
  where je.status in ('posted', 'reversed')
  group by je.org_id, jl.store_id, jl.account_id, je.period_id, a.code, a.name, a.type, a.normal_balance
);--> statement-breakpoint
CREATE VIEW "public"."v_income_statement" AS (
  select
    je.org_id as org_id,
    jl.store_id as store_id,
    jl.account_id as account_id,
    a.code as account_code,
    a.name as account_name,
    a.type as account_type,
    (case hdr.code
      when '4000' then 'revenue'
      when '5000' then 'cost_of_sales'
      when '6000' then 'operating_expense'
      when '7000' then 'other_income_expense'
      else 'other'
    end) as category,
    je.entry_date as entry_date,
    je.source_type as source_type,
    coalesce(sum(jl.debit), 0)::numeric(14,2) as debit_total,
    coalesce(sum(jl.credit), 0)::numeric(14,2) as credit_total,
    (case
      when a.type = 'income' then coalesce(sum(jl.credit), 0) - coalesce(sum(jl.debit), 0)
      else coalesce(sum(jl.debit), 0) - coalesce(sum(jl.credit), 0)
    end)::numeric(14,2) as net_amount
  from journal_lines jl
  join journal_entries je on je.id = jl.entry_id
  join accounts a on a.id = jl.account_id
  left join accounts hdr on hdr.id = a.parent_id
  where je.status in ('posted', 'reversed')
    and a.type in ('income', 'expense')
  group by je.org_id, jl.store_id, jl.account_id, a.code, a.name, a.type, hdr.code, je.entry_date, je.source_type
);--> statement-breakpoint
CREATE VIEW "public"."v_trial_balance" AS (
  select
    je.org_id as org_id,
    jl.store_id as store_id,
    jl.account_id as account_id,
    a.code as account_code,
    a.name as account_name,
    a.type as account_type,
    a.normal_balance as normal_balance,
    je.entry_date as entry_date,
    je.source_type as source_type,
    coalesce(sum(jl.debit), 0)::numeric(14,2) as debit_total,
    coalesce(sum(jl.credit), 0)::numeric(14,2) as credit_total,
    (case
      when a.normal_balance = 'debit' then coalesce(sum(jl.debit), 0) - coalesce(sum(jl.credit), 0)
      else coalesce(sum(jl.credit), 0) - coalesce(sum(jl.debit), 0)
    end)::numeric(14,2) as net_balance
  from journal_lines jl
  join journal_entries je on je.id = jl.entry_id
  join accounts a on a.id = jl.account_id
  where je.status in ('posted', 'reversed')
  group by je.org_id, jl.store_id, jl.account_id, a.code, a.name, a.type, a.normal_balance, je.entry_date, je.source_type
);